def penalize_decimal_answer_for_integer_gt(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        try:
            text = completion[0]['content']
            sol_match = re.search(r'<solution>(.*?)</solution>', text, re.DOTALL)
            pred_str = sol_match.group(1).strip() if sol_match else ''

            gt_is_int = re.fullmatch(r'\d+', gt.strip()) is not None
            if not gt_is_int:
                scores.append(0.0)
                continue

            if is_correct(pred_str, gt):
                scores.append(0.0)
                continue

            pred_clean = pred_str.replace(' ', '').replace(',', '')
            if re.search(r'\d+\.\d+', pred_clean):
                scores.append(-1.5)
            else:
                scores.append(0.0)
        except Exception:
            scores.append(0.0)
    return scores

def penalize_repetitive_equation_loops(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        try:
            text = completion[0]['content']
            think_match = re.search(r'<thinking>(.*?)</thinking>', text, re.DOTALL)
            thinking = think_match.group(1) if think_match else ''

            lines = [line.strip() for line in thinking.split('\n') if line.strip()]
            penalty = 0.0
            for i in range(len(lines) - 2):
                if lines[i] == lines[i+1] == lines[i+2]:
                    if re.search(r'[=\d]', lines[i]):
                        penalty -= 0.5
            scores.append(max(-2.0, penalty))
        except Exception:
            scores.append(0.0)
    return scores

def penalize_truncated_incomplete_thinking(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        try:
            text = completion[0]['content']
            if '</thinking>' not in text:
                scores.append(-1.5)
                continue

            think_match = re.search(r'<thinking>(.*?)</thinking>', text, re.DOTALL)
            thinking = think_match.group(1) if think_match else ''

            if thinking and not thinking.rstrip().endswith(('.', '!', '?', '}', ']', ')')):
                if re.search(r'\\[a-zA-Z]+$', thinking.rstrip()):
                    scores.append(-1.0)
                else:
                    scores.append(0.0)
            else:
                scores.append(0.0)
        except Exception:
            scores.append(0.0)
    return scores

